@rendermode InteractiveServer

@using sv_bad1b62a335f417e859b6c22d74b5496.Models
@using sv_bad1b62a335f417e859b6c22d74b5496.Services

@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepSelected="GoToStep" />

    <hr class="mb-4" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep Model="personalInfo"
                              OnNext="NextStep" />
            break;
        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 3:
            <ReferencesStep References="references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 4:
            <CoverLetterStep @bind-CoverLetter="coverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 5:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="coverLetter"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication"
                        OnBack="PreviousStep" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private bool isSubmitted;
    private int applicationId;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 5)
        {
            currentStep++;
        }
    }

    private void PreviousStep()
    {
        if (currentStep > 1)
        {
            currentStep--;
        }
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            Personal: new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            Work: new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company,
                e.Title,
                e.StartDate ?? DateTime.MinValue,
                e.IsCurrent ? null : e.EndDate,
                e.Description
            )).ToList()),
            References: references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            CoverLetter: coverLetter
        );

        applicationId = await AppService.SubmitApplicationAsync(application);
        isSubmitted = true;
        completedSteps.Add(5);
    }
}
"}

