@* Step progress bar showing all 5 steps with status indicators *@

<nav class="step-indicator mb-4" aria-label="Application progress">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < Steps.Count; i++)
        {
            var step = i + 1;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;

            <div class="step-item text-center flex-fill"
                 role="listitem"
                 style="cursor: @(isCompleted ? "pointer" : "default"); z-index: 1;"
                 @onclick="() => HandleClick(step)">
                <div class="step-circle mx-auto mb-2 rounded-circle d-flex align-items-center justify-content-center fw-bold"
                     style="width: 40px; height: 40px;
                            background: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#e9ecef");
                            color: @(isCurrent || isCompleted ? "white" : "#adb5bd");
                            border: 2px solid @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#dee2e6");
                            transition: all 0.2s;">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="d-block @(isCurrent ? "fw-semibold text-primary" : isCompleted ? "text-success" : "text-muted")">
                    @Steps[i]
                </small>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> Steps = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

